'use strict';
const STORAGE='aptech-ai-session5-v1';
const CORE_CODE='from openai import OpenAI\nclient = OpenAI()\nprompt = "Explain a Python variable in one sentence."\nresponse = client.responses.create(\n    model="gpt-6-astra",\n    instructions="Teach a beginner using simple words.",\n    input=prompt,\n    max_output_tokens=512,\n    store=False,\n)\nprint(response.output_text)';
const fresh={slide:0,answers:{},worksheet:{},variableName:'topic',variableValue:'Python variables',literalPrint:false,requestModel:'gpt-6-astra',requestQuestion:'Explain a Python variable in one sentence.',requestInstructions:'Teach a beginner using simple words.',requestStep:0,requestOutput:'',role:'developer',prompt:{task:'Explain what a Python variable does.',audience:'A student who has never programmed.',format:'One short sentence and one Python example.',evidence:'name = "Amina" stores the text Amina under the name name.',constraints:'Use simple words. Do not claim the computer understands names like a person.'},fewLabels:{BOOKING:'BOOKING',HOURS:'HOURS',SAFETY:'SAFETY'},useExamples:true,fewQuestion:'hours',fewOutput:'',jsonText:'{"label":"HOURS"}',jsonOutput:'',studentName:'Amina',includeHistory:true,historyOutput:'',historyPacket:'',historyStep:0,contextTurns:5,evalOutput:null};
let state;try{state={...structuredClone(fresh),...JSON.parse(localStorage.getItem(STORAGE)||'null')};}catch(e){state=structuredClone(fresh);}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));return true;}catch(e){return false;}}
const sections=[{name:'Reconnect and set the task',time:10,start:0},{name:'APIs and the course models',time:10,start:3},{name:'Python foundations and setup',time:20,start:7},{name:'Understand the first request',time:20,start:12},{name:'Create and refine prompts',time:15,start:17},{name:'Few-shot examples and format',time:15,start:22},{name:'Conversation context',time:15,start:26},{name:'Evaluate, build, and practise',time:15,start:32}];
function sectionFor(i){return sections.filter(s=>s.start<=i).at(-1);}
function panel(title,text,classes=''){return '<article class="panel stack '+classes+'"><h3>'+title+'</h3><p>'+text+'</p></article>';}
function note(text){return '<div class="note">'+text+'</div>';}
function field(key,label,placeholder=''){return '<label>'+esc(label)+'<textarea class="answer" data-field="'+key+'" placeholder="'+esc(placeholder)+'">'+esc(state.worksheet[key]||'')+'</textarea></label>';}
const docs={quick:'https://developers.openai.com/api/docs/quickstart',legacy35:'https://developers.openai.com/api/docs/models/gpt-3.5-turbo',legacy4:'https://developers.openai.com/api/docs/models/gpt-4-turbo-preview',deprecations:'https://developers.openai.com/api/docs/deprecations',prompt:'https://developers.openai.com/api/docs/guides/prompt-engineering',history:'https://developers.openai.com/api/docs/guides/conversation-state',reference:'https://developers.openai.com/api/reference/python/resources/responses/methods/create',structured:'https://developers.openai.com/api/docs/guides/structured-outputs'};
function sourceLink(key,label){return '<a href="'+docs[key]+'" target="_blank" rel="noopener" class="caption">'+label+'</a>';}
const quizData={recall:{q:'An assistant gives a fluent answer. What habit from Session 4 should we keep?',options:['Assume fluent language proves it is correct.','Check the answer against the task and relevant evidence.'],correct:1,why:'An API makes model output available to your program. You still need to inspect factual support, usefulness, and mistakes.'},api:{q:'What does an API let your Python program do here?',options:['Send a request to a model service and receive a response.','Install human understanding inside Python.'],correct:0,why:'An API is an interface between programs. The SDK helps construct requests and read responses.'},key:{q:'Where should a real API key go?',options:['Inside a shared HTML presentation or submitted source file.','In a private environment setting or hidden local entry used by the program.'],correct:1,why:'A key authorises requests. The classroom browser labs never ask for one. The optional live Python examples use a hidden prompt or a private environment value.'},few:{q:'What do few-shot examples change during an ordinary API request?',options:['They provide patterns in the request’s context.','They retrain and permanently update the model’s weights.'],correct:0,why:'A few-shot prompt includes example inputs and desired outputs. That differs from fine-tuning or training.'},history:{q:'Why does a follow-up request need relevant earlier context?',options:['Every independent call automatically remembers every previous call.','The application must send earlier messages or link the request to supported conversation state.'],correct:1,why:'An independent request does not automatically inherit your application’s history. You decide what context to include or how to link state.'},exit1:{q:'In input=prompt, what is prompt?',options:['The current value stored in a variable named prompt.','A secret Python keyword that automatically improves answers.'],correct:0,why:'The variable holds text. The named argument input receives that text value.'},exit2:{q:'Is valid JSON enough to prove a classification is correct?',options:['Yes. A valid format guarantees the right meaning.','No. Check the allowed structure and the actual label too.'],correct:1,why:'Syntax, schema, and correctness are different checks. {"label":"BOOKING"} is valid JSON but is wrong for a question about opening hours.'},exit3:{q:'When using previous_response_id, do previous instructions automatically carry forward?',options:['Yes, so the next call can always omit them.','No. Provide instructions again when they should still apply.'],correct:1,why:'The Responses API documentation says previous instructions are not carried over with previous_response_id. Repeat the instructions you want on the next turn.'}};
function quiz(id){const q=quizData[id],a=state.answers[id];return '<div class="stack"><h3>'+q.q+'</h3><div class="choices">'+q.options.map((o,i)=>'<button data-quiz="'+id+'" data-choice="'+i+'" aria-pressed="'+(a===i)+'">'+o+'</button>').join('')+'</div><div class="feedback '+(a!==undefined&&a!==q.correct?'bad':'')+'" id="feedback-'+id+'" aria-live="polite">'+(a===undefined?'':(a===q.correct?'Yes. ':'Review the reason. ')+q.why)+'</div></div>';}
const retired=['gpt-3.5-turbo','gpt-3.5-turbo-0125','gpt-4-turbo-preview','gpt-4-0125-preview'];
function variableDemo(name,value,literal=false){if(!/^[A-Za-z_]\w*$/.test(name)||['True','False','None','if','else','for','while','class','def','return','import','from','and','or','not','print','as','assert','async','await','break','continue','del','elif','except','finally','global','in','is','lambda','nonlocal','pass','raise','try','with','yield'].includes(name))return {ok:false,code:'',output:'Choose a valid variable name: letters or underscore first, then letters, digits, or underscores. Avoid Python keywords and print in this exercise.'};return {ok:true,code:name+' = '+JSON.stringify(value)+'\nprint('+(literal?JSON.stringify(name):name)+')',output:literal?name:value};}
function variableHTML(){return '<div class="lab05"><div class="stack"><label class="field05">Variable name<input id="variableName" type="text" value="'+esc(state.variableName)+'" maxlength="40"></label><label class="field05">Text to store<input id="variableValue" type="text" value="'+esc(state.variableValue)+'" maxlength="180"></label><label class="row"><input id="literalPrint" type="checkbox" '+(state.literalPrint?'checked':'')+'> Put quotes around the name inside print</label><button id="assignPrint" class="accent">Assign, then print</button><p class="caption">A local illustration of these two Python lines. No full Python interpreter or model call runs in this page.</p></div><div class="stack"><h3>Python illustration</h3><pre id="variableCode" class="code"></pre><h3>Displayed output</h3><div id="variableOutput" class="output05" aria-live="polite"></div><a href="string_foundations.py" download class="caption">Download the matching standalone Python exercise</a></div></div>';}
function updateVariable(){const r=variableDemo(state.variableName,state.variableValue,state.literalPrint);document.getElementById('variableCode').textContent=r.code||'Fix the name to construct the example.';document.getElementById('variableOutput').textContent=r.output;document.getElementById('variableOutput').classList.toggle('bad',!r.ok);}
function requestPacket(){return {model:state.requestModel,instructions:state.requestInstructions,input:state.requestQuestion,max_output_tokens:512,store:false};}
function mockExplain(input){const p=input.toLowerCase();return /variable/.test(p)?'A variable is a name your program uses to store and find a value.':/api/.test(p)?'An API lets one program request a service from another program.':/precision/.test(p)?'Precision measures how many of the examples flagged as positive were actually positive.':'This local demo has no scripted answer for that topic. A real model request would generate a response.';}
function requestResult(packet){if(!packet.model.trim())return {ok:false,text:'Demo error: choose a model ID.'};if(retired.includes(packet.model))return {ok:false,text:'Demo error: this course model ID is retired. Compare it historically, then choose the current documented example.'};if(!packet.input.trim())return {ok:false,text:'Demo error: provide a question in input.'};return {ok:true,id:'demo_response_1',text:mockExplain(packet.input)};}
const requestSteps=['Read the Python values.','Construct the request fields.','SDK sends an authenticated request (simulated here).','The service processes the input (scripted here).','Receive and inspect a response object.'];
function requestHTML(){return '<div class="lab05"><div class="stack"><div class="control05"><label class="field05">Model<select id="requestModel">'+[['gpt-6-astra','gpt-6-astra · docs example'],['gpt-3.5-turbo','gpt-3.5-turbo · retired'],['gpt-4-turbo-preview','gpt-4-turbo-preview · retired']].map(([v,n])=>'<option value="'+v+'" '+(state.requestModel===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="field05">Scripted topic<select id="requestTopic"><option value="custom">Custom input</option><option value="variable">Python variable</option><option value="api">API</option><option value="precision">Precision</option></select></label><label class="field05 wide">Instructions<textarea id="requestInstructions" maxlength="600">'+esc(state.requestInstructions)+'</textarea></label><label class="field05 wide">Input<textarea id="requestQuestion" maxlength="600">'+esc(state.requestQuestion)+'</textarea></label></div><div class="row"><button id="requestStep" class="accent">Next request step</button><button id="requestRun">Show all steps</button><button id="requestReset">Reset</button></div><p class="caption">Offline request simulation. No HTTP request, API key, billing, or AI model runs. Instructions appear in the packet but do not alter this canned answer.</p></div><div class="stack"><pre id="requestPacket" class="request05"></pre><div id="requestTrace" class="trace05"></div><p id="requestDetail" class="trace-detail05"></p><div id="requestOutput" class="output05" aria-live="polite"></div></div></div>';}
function updateRequest(){document.getElementById('requestTopic').value=/precision/i.test(state.requestQuestion)?'precision':/api/i.test(state.requestQuestion)?'api':/variable/i.test(state.requestQuestion)?'variable':'custom';const packet=requestPacket();document.getElementById('requestPacket').textContent=JSON.stringify(packet,null,2);document.getElementById('requestTrace').innerHTML=requestSteps.map((t,i)=>'<div class="trace-step05 '+(state.requestStep>i?'done':state.requestStep===i?'active':'')+'"><b>'+String(i+1)+'</b>'+t+'</div>').join('');document.getElementById('requestDetail').textContent=requestSteps[Math.min(4,state.requestStep)];const out=document.getElementById('requestOutput');if(state.requestStep<5){out.textContent='Predict the packet and response before completing the trace.';out.classList.remove('bad');}else{const r=requestResult(packet);state.requestOutput=r.text;save();out.classList.toggle('bad',!r.ok);out.innerHTML='<span>'+esc(r.text)+'</span><small>'+esc(r.ok?r.id+' · scripted output': 'Local demonstration error, not an API response')+'</small>';}document.getElementById('requestStep').disabled=state.requestStep>=5;}
const codeLines=[['from openai import OpenAI','Import the OpenAI client class from the installed openai package. from identifies the package. import brings a named tool into this file.'],['client = OpenAI()','Call the client constructor and store the client object. In this minimal live snippet, it reads OPENAI_API_KEY from the environment. Constructing a client alone does not generate an answer.'],['prompt = "Explain a Python variable in one sentence."','Assign a text string to the variable prompt. Quotation marks define the text. A meaningful variable name helps us reuse or change the value.'],['response = client.responses.create(','Follow the client’s responses interface and call its create method. The opening parenthesis begins the argument list. This is the line that starts the model request when real Python reaches it.'],['    model="gpt-6-astra",','Pass a named argument: model is the parameter name, the quoted value is a model ID. The comma separates it from the next argument. This is the current documentation example, not a promise of access or lowest price.'],['    instructions="Teach a beginner using simple words.",','Supply the intended behaviour separately from the user’s current task. Instructions have higher priority than conflicting input text, though outputs still need checking.'],['    input=prompt,','Pass the value stored in prompt. Without quotes, Python looks up the variable. input="prompt" would instead send the literal word prompt.'],['    max_output_tokens=512,','Set an upper bound on generated tokens, including reasoning tokens where applicable. It is a token count, not 512 words and not a guaranteed answer length.'],['    store=False,','Request that the response object not be saved for later retrieval. This does not mean every service log is disabled or that context is never retained by your application.'],[')','Close the argument list. Python allows a multiline call inside parentheses. Indentation here improves readability and differs from the required block indentation after if.'],['print(response.output_text)','Access the returned object’s text helper and display it. The full object contains more fields. A refusal or incomplete response may need separate handling.']];
function promptText(p){return [['Task',p.task],['Audience',p.audience],['Output format',p.format],['Provided facts',p.evidence],['Limits',p.constraints]].filter(([,v])=>v.trim()).map(([k,v])=>k+': '+v.trim()).join('\n\n');}
function promptChecks(p){return [['Task stated',Boolean(p.task.trim())],['Audience stated',Boolean(p.audience.trim())],['Format stated',Boolean(p.format.trim())],['Evidence supplied',Boolean(p.evidence.trim())],['Limits stated',Boolean(p.constraints.trim())]];}
function promptHTML(){return '<div class="lab05"><div class="stack"><div class="prompt-fields05">'+[['task','Task'],['audience','Audience'],['format','Output format'],['evidence','Provided facts'],['constraints','Limits']].map(([k,n])=>'<label class="field05 '+(k==='constraints'?'wide':'')+'">'+n+'<textarea data-prompt-field="'+k+'" maxlength="900">'+esc(state.prompt[k])+'</textarea></label>').join('')+'</div><div class="row"><button id="weakPrompt">Vague example</button><button id="strongPrompt">Clear example</button><button id="downloadPrompt" class="accent">Download prompt</button></div></div><div class="stack"><pre id="promptOutput" class="prompt-output05"></pre><div id="promptChecks" class="checklist05"></div><p class="caption">This checklist checks whether fields contain text. It does not measure a model’s answer quality or verify your evidence.</p></div></div>';}
function updatePrompt(){document.getElementById('promptOutput').textContent=promptText(state.prompt)||'Add a task and relevant details.';document.getElementById('promptChecks').innerHTML=promptChecks(state.prompt).map(([n,v])=>'<div class="check-item05 '+(v?'pass':'')+'">'+(v?'✓ ':'○ ')+n+'</div>').join('');}
const examples=[{topic:'BOOKING',input:'Please reserve Lab 2.'},{topic:'HOURS',input:'When does the lab open?'},{topic:'SAFETY',input:'Is safety training required?'}];
const fewInputs={booking:'Can you book a practice slot tomorrow?',hours:'At what time does Lab 2 close?',safety:'Do I need safety training for entry?',unknown:'Can I bring a guest?'};
function topicFor(text){return /safety|training/i.test(text)?'SAFETY':/when|time|open|close|hours/i.test(text)?'HOURS':/book|reserve|slot/i.test(text)?'BOOKING':'UNKNOWN';}
function scriptedLabel(text,labels,useExamples=true){const topic=topicFor(text);return !useExamples?'This seems to be a '+topic.toLowerCase()+' question.':topic==='UNKNOWN'?'UNKNOWN':labels[topic];}
function fewPacket(){const messages=state.useExamples?examples.flatMap(e=>[{role:'user',content:e.input},{role:'assistant',content:state.fewLabels[e.topic]}]):[];messages.push({role:'user',content:fewInputs[state.fewQuestion]});return messages;}
function fewHTML(){return '<div class="lab05"><div class="stack"><h3>Example inputs and outputs</h3><div class="few-demo05">'+examples.map(e=>'<label class="few-row05"><span>'+e.input+'<small>Example topic: '+e.topic+'</small></span><select data-few-label="'+e.topic+'">'+['BOOKING','HOURS','SAFETY','UNKNOWN'].map(v=>'<option value="'+v+'" '+(v===state.fewLabels[e.topic]?'selected':'')+'>'+v+'</option>').join('')+'</select></label>').join('')+'</div><label class="row"><input id="useExamples" type="checkbox" '+(state.useExamples?'checked':'')+'> Include these examples</label><label class="field05">New input<select id="fewQuestion">'+Object.entries(fewInputs).map(([k,v])=>'<option value="'+k+'" '+(k===state.fewQuestion?'selected':'')+'>'+v+'</option>').join('')+'</select></label><button id="fewRun" class="accent">Show scripted classification</button><p class="caption">The stand-in uses visible keyword rules and your example-label mapping. It is not a language model. Real few-shot results can differ.</p></div><div class="stack"><pre id="fewPacket" class="request05"></pre><div id="fewOutput" class="output05" aria-live="polite">'+esc(state.fewOutput||'Predict a label before showing it.')+'</div></div></div>';}
function updateFew(){document.getElementById('fewPacket').textContent='[\n'+fewPacket().map(m=>'  '+JSON.stringify(m)).join(',\n')+'\n]';}
function validateJSON(text,expected='HOURS'){let obj;try{obj=JSON.parse(text);}catch(e){return {syntax:false,schema:false,meaning:false,message:'JSON syntax failed. Use double quotes, balanced braces, and no trailing comma.'};}if(!obj||Array.isArray(obj)||typeof obj!=='object'||Object.keys(obj).length!==1||!Object.hasOwn(obj,'label')||!['BOOKING','HOURS','SAFETY','UNKNOWN'].includes(obj.label))return {syntax:true,schema:false,meaning:false,message:'JSON syntax passed. Shape failed: use exactly one key, label, with an allowed label.'};const meaning=obj.label===expected;return {syntax:true,schema:true,meaning,message:'JSON syntax passed. Allowed shape passed. '+(meaning?'Meaning matches the hours question.':'Meaning failed: this hours question should have label HOURS.')};}
function jsonHTML(){return '<div class="lab05"><div class="stack"><p>Question: “At what time does Lab 2 close?”</p><textarea id="jsonEditor" class="json-editor05" spellcheck="false" aria-label="JSON to validate">'+esc(state.jsonText)+'</textarea><div class="tabs05"><button data-json-example="correct">Correct</button><button data-json-example="syntax">Trailing comma</button><button data-json-example="shape">Wrong key</button><button data-json-example="meaning">Wrong meaning</button></div><button id="validateJSON" class="accent">Check syntax, shape, and meaning</button></div><div class="stack"><div id="jsonResult" class="output05" aria-live="polite">'+esc(state.jsonOutput||'Predict which checks should pass.')+'</div>'+panel('Three different checks','A response can be valid JSON while using the wrong fields or giving the wrong answer.')+sourceLink('structured','Further reading: Structured Outputs')+'</div></div>';}
function historyMessages(name){return [{role:'user',content:'My name is '+name+'.'},{role:'assistant',content:'Thanks. I will use that name in this conversation.'},{role:'user',content:'Greet me by name.'}];}
function historyAnswer(messages){let name=null;for(const m of messages){if(m.role==='user'){const found=m.content.match(/^My name is (.+)\.$/);if(found)name=found[1];}}return name?'Hello, '+name+'!':'What name would you like me to use?';}
function historyHTML(){return '<div class="lab05"><div class="stack"><label class="field05">First-turn name<input id="studentName" type="text" maxlength="60" value="'+esc(state.studentName)+'"></label><div id="historyMessages" class="history-log05"></div><label class="row"><input id="includeHistory" type="checkbox" '+(state.includeHistory?'checked':'')+'> Send the earlier two messages with the follow-up</label><button id="historyRun" class="accent">Show scripted follow-up</button><p class="caption">A scripted illustration of supplied context. It reads the name from the included user message. This is not a model or persistent personal memory.</p></div><div class="stack"><h3>What this request includes</h3><pre id="historyPacket" class="request05"></pre><div id="historyOutput" class="output05" aria-live="polite">'+esc(state.historyOutput||'Will the new request contain the name?')+'</div></div></div>';}
function updateHistory(){const all=historyMessages(state.studentName||'Amina'),sent=state.includeHistory?all:all.slice(-1);document.getElementById('historyMessages').innerHTML=all.map((m,i)=>'<div class="history-item05 '+(m.role==='user'?'user ':'')+(!state.includeHistory&&i<2?'excluded':'')+'"><b>'+m.role+(i<2&&!state.includeHistory?' · excluded from this request':'')+'</b>'+esc(m.content)+'</div>').join('');document.getElementById('historyPacket').textContent='[\n'+sent.map(m=>'  '+JSON.stringify(m)).join(',\n')+'\n]';}
function contextBudget(turns){const input=40+80*turns,reserved=160,windowSize=1024,total=input+reserved;return {input,reserved,total,windowSize,remaining:windowSize-total,overflow:total>windowSize};}
function contextHTML(){return '<div class="stack"><label class="field05" for="contextTurns">Conversation turns in this fictional example: <output id="contextTurnsValue"></output><input id="contextTurns" type="range" min="0" max="20" step="1" value="'+state.contextTurns+'"></label><div id="contextStats" class="context-stats05"></div><div class="meter05" id="contextMeter"><div id="contextFill"></div></div><div id="contextResult" class="output05" aria-live="polite"></div><p class="caption">Toy budget: 40 instruction tokens, 80 per turn, 160 reserved output/reasoning tokens, 1,024 total capacity. These are fictional counts, not a current OpenAI model’s limits.</p></div>';}
function updateContext(){const b=contextBudget(state.contextTurns);document.getElementById('contextTurnsValue').textContent=state.contextTurns;document.getElementById('contextStats').innerHTML=[['Input budget',b.input],['Output reserved',b.reserved],['Capacity remaining',b.remaining]].map(([n,v])=>'<div class="context-stat05">'+n+'<b>'+v+'</b></div>').join('');document.getElementById('contextFill').style.width=Math.min(100,b.total/b.windowSize*100)+'%';document.getElementById('contextMeter').classList.toggle('over',b.overflow);const f=document.getElementById('contextResult');f.classList.toggle('bad',b.overflow);f.textContent=b.overflow?'The toy request exceeds its budget. Select relevant context or summarise carefully before sending.':'The toy request fits. Sending a larger history still uses more input tokens.';}
const evaluationCases=[{input:'Could I reserve a place in Lab 2?',expected:'BOOKING'},{input:'Tell me the opening hours.',expected:'HOURS'},{input:'Must I complete the safety course?',expected:'SAFETY'},{input:'Is there a visitor fee?',expected:'UNKNOWN'}];
function evaluateLabels(labels,useExamples){const rows=evaluationCases.map(t=>{const actual=scriptedLabel(t.input,labels,useExamples);return {...t,actual,correct:actual===t.expected,format:['BOOKING','HOURS','SAFETY','UNKNOWN'].includes(actual)};});return {rows,correct:rows.filter(r=>r.correct).length,format:rows.filter(r=>r.format).length,total:rows.length};}
function evaluationHTML(){return '<div class="lab05"><div class="stack"><p>Use four new inputs that differ from the example inputs. Keep the expected labels fixed while changing your prompt examples.</p><div class="row"><button id="evaluateLabels" class="accent">Run scripted checks</button><button data-go="23">Edit the examples</button><button id="resetExamples">Restore correct examples</button></div><div id="evalSummary" class="eval-summary05"></div><p class="caption">These results evaluate our transparent stand-in, not an OpenAI model. Repeat the same cases against real model outputs during optional live practice.</p></div><div class="panel"><table class="small-table eval-table05"><thead><tr><th>Input</th><th>Expected</th><th>Output</th></tr></thead><tbody id="evalRows"></tbody></table></div></div>';}
function updateEvaluation(){const r=state.evalOutput||evaluateLabels(state.fewLabels,state.useExamples);document.getElementById('evalSummary').innerHTML='<div>Correct labels<b>'+r.correct+' / '+r.total+'</b></div><div>Allowed output format<b>'+r.format+' / '+r.total+'</b></div>';document.getElementById('evalRows').innerHTML=r.rows.map(t=>'<tr class="'+(!t.correct?'failed':'')+'"><td>'+esc(t.input)+'</td><td>'+t.expected+'</td><td>'+esc(t.actual)+'</td></tr>').join('');}
