const glossary=[['API','Application programming interface: a defined way for programs to request a service and receive results.'],['SDK','Software development kit: tools such as the Python client for using an API.'],['Client','An object configured to interact with a service.'],['Model ID','The string that identifies which model a request should use.'],['Import','Make tools from a Python package available to a source file.'],['Package','Installable Python code that supplies reusable functionality.'],['Virtual environment','A separate Python package environment for a project.'],['Terminal','A place to issue commands and inspect program output.'],['API key','A private credential that authorises API requests.'],['Environment variable','A named configuration value made available to a process.'],['String','A text value enclosed by quotation marks in Python source.'],['Variable','A name associated with a stored value in a program.'],['Dictionary','A mapping from keys to values, written with braces in Python.'],['List','An ordered collection of items, written with square brackets.'],['Named argument','A parameter name with the value passed to a function or method call.'],['Method','An operation accessed through an object, such as history.append(...).'],['Prompt','Instructions and task content supplied to guide a model response.'],['Instructions','Higher-priority behaviour guidance supplied through the Responses instructions parameter in this lesson.'],['Message role','A label identifying whether content comes from a user, assistant, or other supported source.'],['Few-shot prompting','Including a few input/output demonstrations in the model context.'],['Fine-tuning','A separate training process that updates model parameters, unlike ordinary few-shot context.'],['Response object','The returned structured result with fields such as id, status, output, and usage.'],['output_text','A Python SDK helper that gathers text output for a response.'],['JSON','A structured data notation with rules for objects, arrays, strings, and other values.'],['Schema','A definition of the allowed structure and values of data.'],['Conversation history','Earlier turns deliberately supplied or linked as context for a follow-up.'],['previous_response_id','Responses parameter that links a request to a prior supported response.'],['Token','A processing unit that may be a piece of a word, rather than one word.'],['Context window','A model’s finite token capacity for the context and generated content under its rules.'],['max_output_tokens','A Responses upper bound on generated tokens, including reasoning where applicable.'],['store=False','Requests that a response object not be saved for later retrieval; it does not disable all service logs.'],['Mock / stand-in','Local scripted behaviour used to practise program flow without calling a real model.'],['Held-out case','A test example kept separate from the demonstrations used to guide the system.'],['Rate limit','A restriction on request or token throughput.'],['Refusal','A response that declines to fulfil a request rather than providing the requested content.'],['Incomplete response','A result that stopped without a completed answer and needs status/detail inspection.']];
const stage=document.getElementById('stage');let lastFocus=null,seconds=7200,timerRunning=false,timerInterval=null;
function go(i){state.slide=Math.max(0,Math.min(slides.length-1,Number(i)||0));save();render();window.scrollTo({top:0,behavior:'instant'});}
function render(){const i=state.slide,s=slides[i];document.title='Session 05 · '+s.title;stage.innerHTML='<article class="slide session05"><div class="slide-head"><div class="section-label"><span class="rule"></span><span class="eyebrow">'+esc(s.kicker)+'</span></div>'+(i===0?'':'<h2>'+esc(s.title)+'</h2>')+'</div>'+s.html()+'</article>';document.getElementById('pageLabel').textContent=(i+1)+' / '+slides.length+' · '+sectionFor(i).name;document.getElementById('prevBtn').disabled=i===0;document.getElementById('nextBtn').disabled=i===slides.length-1;document.getElementById('progressFill').style.width=((i+1)/slides.length*100)+'%';document.getElementById('progress').setAttribute('aria-valuenow',i+1);document.getElementById('progress').setAttribute('aria-valuemax',slides.length);if(i===10)updateVariable();if(i===13)updateRequest();if(i===19)updatePrompt();if(i===23)updateFew();if(i===27)updateHistory();if(i===31)updateContext();if(i===34)updateEvaluation();}
function downloadText(name,body){const url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadWork(){const labels={promptDraft:'Prompt assignment',promptReason:'Prompt evaluation and reason',assistantPlan:'Campus assistant prompt and examples',assistantHistory:'Follow-up context',exitWhy:'Why understanding the request matters'};const p=['FOUNDATIONS OF AI · SESSION 05','Student worksheet · '+new Date().toLocaleDateString()];for(const [k,n] of Object.entries(labels))p.push(n+'\n'+(state.worksheet[k]||'[Not answered]'));p.push('ASSEMBLED PROMPT\n'+promptText(state.prompt),'REQUEST SIMULATION\n'+JSON.stringify(requestPacket(),null,2),'LAST SCRIPTED REQUEST OUTPUT\n'+(state.requestOutput||'[Not run]'),'FEW-SHOT EXAMPLE LABELS\n'+JSON.stringify(state.fewLabels),'LAST SCRIPTED FEW-SHOT OUTPUT\n'+(state.fewOutput||'[Not run]'),'JSON CHECK\n'+state.jsonText+'\n'+state.jsonOutput,'CONTEXT EXPERIMENT\n'+(state.historyOutput||'[Not run]'),'LAST SCRIPTED EVALUATION\n'+JSON.stringify(state.evalOutput||'[Not run]'),'QUICK CHECKS');for(const [id,q] of Object.entries(quizData))p.push(id+': '+(state.answers[id]===undefined?'not answered':state.answers[id]===q.correct?'correct':'review needed'));p.push('All browser outputs are local illustrations, scripted stand-ins, or explicit format checks. No model requests were made by this page.');downloadText('session-05-my-worksheet.txt',p.join('\n\n'));}
function glossaryHTML(query=''){return glossary.filter(x=>x.join(' ').toLowerCase().includes(query.toLowerCase())).map(([w,m])=>'<div class="glossary-item"><b>'+esc(w)+'</b><p>'+esc(m)+'</p></div>').join('')||'<p>No matching term.</p>';}
function timerText(){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function updateTimer(){const v=document.getElementById('timerValue'),b=document.getElementById('timerToggle');if(v)v.textContent=timerText();if(b)b.textContent=timerRunning?'Pause':'Start';}
function openDrawer(type){lastFocus=document.activeElement;document.getElementById('drawer').hidden=false;const title=document.getElementById('drawerTitle'),body=document.getElementById('drawerBody');if(type==='outline'){title.textContent='Session contents';body.innerHTML='<div class="panel stack"><div class="row between"><h3>Class timer</h3><b id="timerValue">'+timerText()+'</b></div><div class="row"><button id="timerToggle">'+(timerRunning?'Pause':'Start')+'</button><button id="timerReset">Reset 120 min</button></div></div>'+slides.map((s,i)=>'<button class="outline-button '+(i===state.slide?'current':'')+'" data-outline-go="'+i+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(s.title)+'</button>').join('');}else if(type==='sources'){title.textContent='Sources and coverage';body.innerHTML='<p>Official Aptech class 5 covers Book Session 7: comparison of gpt-3.5-turbo and gpt-4-turbo-preview, Python API conversations, prompt creation/refinement, few-shot examples, and historical context.</p><p>The manual’s exact models remain in the historical comparison. Official documentation checked on 8 November 2026 shows both IDs retired. The current Responses example uses the model ID shown in the official quickstart.</p>'+Object.entries({quick:'OpenAI Python quickstart',legacy35:'GPT-3.5 Turbo historical specification',legacy4:'GPT-4 Turbo Preview historical specification',deprecations:'Official retirement dates',prompt:'Prompt engineering and few-shot guidance',history:'Conversation state and token context',reference:'Python Responses API reference',structured:'Structured Outputs guidance'}).map(([k,n])=>'<a class="source-link05" href="'+docs[k]+'" target="_blank" rel="noopener">'+n+'</a>').join('')+'<p>These activities supplement the supplied presenter’s outline. The full textbook and official question banks were not supplied. Browser activities make no model calls. The Python bundle defaults to local stand-ins and enables network requests only with --live.</p><p>Live response wording, account access, pricing, and limits vary. Read the current documentation and API project settings before class.</p>';}else{title.textContent='Word bank';body.innerHTML='<label for="wordSearch" class="small">Find a term</label><input id="wordSearch" type="text" placeholder="SDK, context, token…"><div id="wordList">'+glossaryHTML()+'</div>';}document.getElementById('closeDrawer').focus();}
function closeDrawer(){document.getElementById('drawer').hidden=true;if(lastFocus?.isConnected)lastFocus.focus();}
stage.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go!==undefined)return go(b.dataset.go);if(b.dataset.quiz){const id=b.dataset.quiz,a=Number(b.dataset.choice),q=quizData[id];state.answers[id]=a;save();document.querySelectorAll('[data-quiz="'+id+'"]').forEach(x=>x.setAttribute('aria-pressed',Number(x.dataset.choice)===a));const f=document.getElementById('feedback-'+id);f.textContent=(a===q.correct?'Yes. ':'Review the reason. ')+q.why;f.classList.toggle('bad',a!==q.correct);}if(b.id==='assignPrint')updateVariable();if(b.id==='requestStep'){state.requestStep=Math.min(5,state.requestStep+1);save();updateRequest();}if(b.id==='requestRun'){state.requestStep=5;save();updateRequest();}if(b.id==='requestReset'){state.requestStep=0;state.requestOutput='';save();updateRequest();}if(b.dataset.codeLine!==undefined){const i=Number(b.dataset.codeLine);document.querySelectorAll('[data-code-line]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('lineDetail').innerHTML='<h3>Line '+(i+1)+'</h3><pre class="code">'+esc(codeLines[i][0])+'</pre><p>'+codeLines[i][1]+'</p>';}if(b.id==='roleRun'){document.getElementById('roleOutput').textContent=state.role==='developer'?'Intended: follow the one-sentence application instruction, such as “A variable is a name for a stored value.”':'Illustration: the later user request may update the earlier user preference to five paragraphs. The application should define its desired rules clearly.';}if(b.id==='weakPrompt'||b.id==='strongPrompt'){state.prompt=b.id==='weakPrompt'?{task:'Tell me about Python.',audience:'',format:'',evidence:'',constraints:''}:structuredClone(fresh.prompt);save();render();}if(b.id==='downloadPrompt')downloadText('session-05-my-prompt.txt',promptText(state.prompt));if(b.id==='fewRun'){state.fewOutput=scriptedLabel(fewInputs[state.fewQuestion],state.fewLabels,state.useExamples);save();document.getElementById('fewOutput').textContent=state.fewOutput;}if(b.dataset.jsonExample){const texts={correct:'{"label":"HOURS"}',syntax:'{"label":"HOURS",}',shape:'{"category":"HOURS"}',meaning:'{"label":"BOOKING"}'};state.jsonText=texts[b.dataset.jsonExample];state.jsonOutput='';save();render();}if(b.id==='validateJSON'){const r=validateJSON(state.jsonText);state.jsonOutput=r.message;save();const f=document.getElementById('jsonResult');f.textContent=r.message;f.classList.toggle('bad',!r.meaning);}if(b.id==='historyRun'){const all=historyMessages(state.studentName||'Amina'),sent=state.includeHistory?all:all.slice(-1);state.historyOutput=historyAnswer(sent);state.historyPacket=JSON.stringify(sent);save();document.getElementById('historyOutput').textContent=state.historyOutput;}if(b.id==='evaluateLabels'){state.evalOutput=evaluateLabels(state.fewLabels,state.useExamples);save();updateEvaluation();}if(b.id==='resetExamples'){state.fewLabels=structuredClone(fresh.fewLabels);state.useExamples=true;state.evalOutput=null;save();updateEvaluation();}if(b.id==='downloadWork'||b.id==='downloadFinal')downloadWork();if(b.id==='sourcesBtn')openDrawer('sources');});
stage.addEventListener('input',e=>{const t=e.target;if(t.dataset.field){state.worksheet[t.dataset.field]=t.value;save();}if(t.dataset.promptField){state.prompt[t.dataset.promptField]=t.value;save();updatePrompt();}if(t.id==='variableName'||t.id==='variableValue'){state[t.id]=t.value;save();}if(t.id==='requestQuestion'||t.id==='requestInstructions'){state[t.id]=t.value;state.requestStep=0;state.requestOutput='';save();updateRequest();}if(t.id==='jsonEditor'){state.jsonText=t.value;state.jsonOutput='';save();document.getElementById('jsonResult').textContent='Run the checks for the edited value.';document.getElementById('jsonResult').classList.remove('bad');}if(t.id==='studentName'){state.studentName=t.value;state.historyOutput='';save();updateHistory();document.getElementById('historyOutput').textContent='Predict the follow-up with the new context.';}if(t.id==='contextTurns'){state.contextTurns=Number(t.value);save();updateContext();}});
stage.addEventListener('change',e=>{const t=e.target;if(t.id==='literalPrint'){state.literalPrint=t.checked;save();updateVariable();}if(t.id==='requestModel'){state.requestModel=t.value;state.requestStep=0;state.requestOutput='';save();updateRequest();}if(t.id==='requestTopic'){state.requestQuestion={variable:'Explain a Python variable in one sentence.',api:'Explain an API in one sentence.',precision:'Explain precision in one sentence.'}[t.value]||state.requestQuestion;state.requestStep=0;state.requestOutput='';save();document.getElementById('requestQuestion').value=state.requestQuestion;updateRequest();}if(t.id==='instructionRole'){state.role=t.value;save();document.getElementById('roleOutput').textContent='Predict the intended behaviour before showing it.';}if(t.dataset.fewLabel||t.id==='useExamples'||t.id==='fewQuestion'){if(t.dataset.fewLabel)state.fewLabels[t.dataset.fewLabel]=t.value;else if(t.id==='useExamples')state.useExamples=t.checked;else state.fewQuestion=t.value;state.fewOutput='';state.evalOutput=null;save();updateFew();document.getElementById('fewOutput').textContent='Predict the new output.';}if(t.id==='includeHistory'){state.includeHistory=t.checked;state.historyOutput='';save();updateHistory();document.getElementById('historyOutput').textContent='Predict whether the name is in this request.';}});
document.getElementById('prevBtn').onclick=()=>go(state.slide-1);document.getElementById('nextBtn').onclick=()=>go(state.slide+1);document.getElementById('outlineBtn').onclick=()=>openDrawer('outline');document.getElementById('glossaryBtn').onclick=()=>openDrawer('glossary');document.getElementById('closeDrawer').onclick=closeDrawer;document.getElementById('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(e){document.getElementById('fullscreenBtn').textContent='Use browser full screen';}};
document.getElementById('drawer').addEventListener('click',e=>{if(e.target.id==='drawer')closeDrawer();const b=e.target.closest('button');if(!b)return;if(b.dataset.outlineGo!==undefined){closeDrawer();go(b.dataset.outlineGo);}if(b.id==='timerToggle'){timerRunning=!timerRunning;if(timerRunning)timerInterval=setInterval(()=>{if(seconds>0)seconds--;else{timerRunning=false;clearInterval(timerInterval);}updateTimer();},1000);else clearInterval(timerInterval);updateTimer();}if(b.id==='timerReset'){seconds=7200;timerRunning=false;clearInterval(timerInterval);updateTimer();}});
document.getElementById('drawer').addEventListener('input',e=>{if(e.target.id==='wordSearch')document.getElementById('wordList').innerHTML=glossaryHTML(e.target.value);});
document.addEventListener('keydown',e=>{const drawer=document.getElementById('drawer');if(e.key==='Escape'&&!drawer.hidden){closeDrawer();return;}if(!drawer.hidden){if(e.key==='Tab'){const all=[...drawer.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='ArrowRight'){e.preventDefault();go(state.slide+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(state.slide-1);}if(e.key==='Home'){e.preventDefault();go(0);}if(e.key==='End'){e.preventDefault();go(slides.length-1);}});
state.slide=Math.max(0,Math.min(slides.length-1,Number(state.slide)||0));render();
